#!/bin/zsh
# Visuels d'ambiance de la proposition « crossover » (10 chapitres de plus). FLUX 3 Klein local, gratuit, passe par la file calcul-lourd.
# Relançable : saute ce qui existe. Usage : gen_crossover.sh [id…]  (sans argument : tout)
cd "$(dirname "$0")/../work/crossover" || exit 1
ST="hand-painted 1990s PC point-and-click adventure game scene, painterly VGA-era look like classic British fantasy adventure games, bold dark outlines, warm saturated colors, humorous storybook fantasy, characters with realistic adult proportions and ironic expressions, wide composition, no text, no letters, no logo, no watermark, no frame"
H="The hero is exactly the man from the reference picture, same face, same blond ponytail, same horned iron Viking helmet, same fur-collared studded leather armor, same round wooden shield on his back, same brown kilt and fur-topped boots, same painted style."
typeset -A P
P[p_orbite]="$H A festive Nordic village party at night in the style of Skyrim: paper lanterns, banquet tables, a big round birthday cake with fifteen lit candles, snowy mountains and fireworks. A huge clumsy giant in furs claps his enormous hands joyfully, and the small hero is flung high up into the starry night sky in a long comic arc, arms and legs flailing, helmet horns first, leaving a sparkling trail. $ST"
P[p_sheo]="A mad prince of madness at a Nordic birthday party at night: a lanky grinning old nobleman with a pointed grey goatee and wild eyes, wearing an extravagant coat split in two halves, one half deep purple and the other half crimson red, with puffy sleeves and gold trim. He holds a big wheel of yellow cheese in one hand and, in the other hand, an old wooden bucket from which glows a swirling purple magic portal. Paper lanterns, banquet tables, snowy mountains behind. $ST"
P[p_charrette]="$H The hero sleeps slumped on the bench of an old wooden horse-drawn prisoner cart, mouth open, snoring. The cart is hurtling through a swirling multicoloured magic vortex tunnel full of glimpses of other worlds, wooden wheels spinning off sparks, a panicked bearded cart driver pulling the reins, a startled brown horse. $ST"
P[r_zelda]="$H Inside a dark rocky cave lit by two small campfires, a wise old man with a long white beard in a red robe solemnly holds out an old wooden bucket to the hero, who looks puzzled. Outside the cave entrance, sunny green hills and a few angry white chickens glaring. $ST"
P[r_minecraft]="$H The hero stands puzzled in a strange world where everything is made of big cubes: blocky square trees, cubic grass hills, a cubic sun, square clouds, a waterfall made of blue blocks. He holds an old wooden bucket of water. Behind him, a tall green blocky cube creature sneaks up silently. The hero himself stays round and hand-painted, not cubic. $ST"
P[r_monkey]="$H A moonlit tropical pirate island harbour at night: a wooden dock, palm trees, a tavern with glowing windows, barrels of grog, a pirate ship at anchor. The hero and a lanky pirate with a long nose and a feathered hat face each other with swords raised in a comic duel, both shouting insults with exaggerated faces. A small stone statue of a monkey with three heads sits on a barrel. $ST"
P[r_potter]="$H A great hall of a wizard school castle: long wooden tables, hundreds of floating candles, a starry enchanted ceiling, robed students staring. On a wooden stool in the centre, the hero sits wearing an old dented wooden bucket on his head instead of a hat, looking proud, while an old patched brown pointed wizard hat lies offended on the floor beside him. $ST"
P[r_jurassic]="$H Night in a rainy tropical jungle in front of a tall broken electric fence with sparks. The hero sits in an old wooden cart and stares at an old wooden bucket of water on the bench beside him: the water in the bucket ripples in perfect circles. Behind the trees, a gigantic toothy dinosaur head is looming in the dark, lit by lightning. $ST"
P[r_starwars]="$H A smoky sci-fi desert cantina bar seen in a wide view: a band of strange big-headed alien musicians playing odd wind instruments on a small stage, bizarre alien patrons at round tables, a round doorway showing a desert with two suns setting. In the centre, the hero stands on a table raising a tankard, singing at the top of his lungs, while the aliens stare at him. $ST"
P[r_anneaux]="$H Inside a colossal dark dwarven underground hall with giant stone pillars, on a very narrow stone bridge over a fiery abyss: an old wizard in grey robes with a long grey beard, a pointed grey hat and a wooden staff stands annoyed, while next to him the hero shouts with all his might, a visible blue rippling shockwave of sound bursting from his mouth toward a huge horned shadow demon of fire and smoke at the other end of the bridge. $ST"
P[r_matrix]="$H A dark shabby room with a red leather armchair, lit by green light, with columns of glowing green falling symbols in the background windows. A calm bald man in a long black leather coat and small round dark sunglasses holds out his two open hands: in one hand a small red potion bottle, in the other a small blue potion bottle. The hero, facing him, already grabs both bottles greedily. $ST"
P[r_thrones]="$H A cold snowy great hall of a northern castle, grey stone, frost, banners. In the centre stands a huge jagged throne made of hundreds of small iron daggers welded together. The hero sits on it uncomfortably, wincing, while outside the window snow falls. $ST"
P[r_portal]="$H A sterile white futuristic test chamber with clean white wall panels and grey floor, one glowing blue oval portal on the left wall and one glowing orange oval portal on the right wall. On a white pedestal sits a big birthday cake with a single candle. A single round red robotic eye hangs from the ceiling on a mechanical arm, watching. The hero, completely out of place, pushes a big wheel of yellow cheese onto a round floor button. $ST"
ids=("$@"); [ ${#ids} -eq 0 ] && ids=(p_orbite p_sheo p_charrette r_zelda r_minecraft r_monkey r_potter r_jurassic r_starwars r_anneaux r_matrix r_thrones r_portal)
for id in $ids; do
  for s in 1 2; do
    out="${id}_$s.png"; [ -f "$out" ] && continue
    seed=$(( ${#id} * 1000 + s * 37 + 11 ))
    if [[ "${P[$id]}" == "$H"* ]]; then flux-image "${P[$id]}" -i hero.png -s 1280x720 --seed $seed -o "$out" >/dev/null 2>&1
    else flux-image "${P[$id]}" -s 1280x720 --seed $seed -o "$out" >/dev/null 2>&1; fi
    echo "$(date +%H:%M:%S) ok $out"
  done
done
